xml.Script:
        clBlue   := '0055EE';
        clBlack  := '333333';
        clViolett:= 'AA00CC';
        clRed    := 'EE0011';
        clGreen  := '00CC00';

        R := 0.6;
        H := R;
        D := (R * sqrt(2) - H) / sqrt(3) * 1.2;

        N := 60;
        for i := 0 to N - 1 do begin
            A := 2*Pi / N * i;
            x[i] := R * cos(A);
            y[i] := R * sin(A);
        end;

        DCut := R / 6;

        for i := 0 to 2 do begin
            ax[i] := cos(2 * Pi / 3 * i);
            ay[i] := sin(2 * Pi / 3 * i);
        end;
        az := 1 / sqrt(2);

        function FromTo(iFrom, iTo);
        begin
            Result := IntToStr(iFrom);
            for i := iFrom + 1 to iTo do
                Result := Result + ';' + IntToStr(i);
            for i := iFrom - 1 downto iTo do
                Result := Result + ';' + IntToStr(i);
        end;

Macro.Script:
i1 := i mod N;
i2 := (i + 1) mod N;
Inc(i);
